package ply

import (
	"bufio"
	"io"
	"reflect"
	"strings"
	"testing"
)

func readHeaderFromString(text string) (header, error) {
	return readHeader(bufio.NewReader(strings.NewReader(text)))
}

func TestReadHeaderParsesElementsAndProperties(t *testing.T) {
	text := "ply\n" +
		"format binary_little_endian 1.0\n" +
		"comment generated by a test\n" +
		"obj_info scanner v1\n" +
		"element vertex 3\n" +
		"property float x\n" +
		"property double y\n" +
		"property uchar red\n" +
		"element face 2\n" +
		"property list uchar int vertex_indices\n" +
		"element edge 0\n" +
		"end_header\n"

	got, err := readHeaderFromString(text)
	if err != nil {
		t.Fatalf("readHeader: %v", err)
	}
	want := header{
		format: formatBinaryLittleEndian,
		elements: []element{
			{name: "vertex", count: 3, properties: []property{
				{name: "x", valueType: float32Type},
				{name: "y", valueType: float64Type},
				{name: "red", valueType: uint8Type},
			}},
			{name: "face", count: 2, properties: []property{
				{name: "vertex_indices", valueType: int32Type, countType: uint8Type},
			}},
			{name: "edge", count: 0},
		},
		dataOffset: int64(len(text)),
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("readHeader mismatch\ngot:  %+v\nwant: %+v", got, want)
	}
	if !got.elements[1].properties[0].isList() || got.elements[0].properties[0].isList() {
		t.Error("isList does not distinguish list and scalar properties")
	}
}

func TestReadHeaderFormats(t *testing.T) {
	tests := map[string]format{
		"ascii":                formatASCII,
		"binary_little_endian": formatBinaryLittleEndian,
		"binary_big_endian":    formatBinaryBigEndian,
	}
	for name, want := range tests {
		t.Run(name, func(t *testing.T) {
			got, err := readHeaderFromString("ply\nformat " + name + " 1.0\nend_header\n")
			if err != nil {
				t.Fatalf("readHeader: %v", err)
			}
			if got.format != want {
				t.Errorf("format = %v, want %v", got.format, want)
			}
		})
	}
}

func TestReadHeaderScalarTypes(t *testing.T) {
	tests := []struct {
		names    []string
		wantType scalarType
		wantSize int
		integer  bool
	}{
		{[]string{"char", "int8"}, int8Type, 1, true},
		{[]string{"uchar", "uint8"}, uint8Type, 1, true},
		{[]string{"short", "int16"}, int16Type, 2, true},
		{[]string{"ushort", "uint16"}, uint16Type, 2, true},
		{[]string{"int", "int32"}, int32Type, 4, true},
		{[]string{"uint", "uint32"}, uint32Type, 4, true},
		{[]string{"float", "float32"}, float32Type, 4, false},
		{[]string{"double", "float64"}, float64Type, 8, false},
	}
	for _, tc := range tests {
		for _, name := range tc.names {
			t.Run(name, func(t *testing.T) {
				h, err := readHeaderFromString("ply\nformat ascii 1.0\nelement vertex 1\nproperty " + name + " v\nend_header\n")
				if err != nil {
					t.Fatalf("readHeader: %v", err)
				}
				got := h.elements[0].properties[0].valueType
				if got != tc.wantType {
					t.Errorf("type = %v, want %v", got, tc.wantType)
				}
				if got.size() != tc.wantSize {
					t.Errorf("size = %d, want %d", got.size(), tc.wantSize)
				}
				if got.isInteger() != tc.integer {
					t.Errorf("isInteger = %v, want %v", got.isInteger(), tc.integer)
				}
			})
		}
	}
}

func TestReadHeaderLeavesReaderAtElementData(t *testing.T) {
	tests := map[string]string{
		"LF":                           "ply\nformat binary_big_endian 1.0\nelement vertex 1\nproperty uchar v\nend_header\n",
		"CRLF":                         "ply\r\nformat binary_big_endian 1.0\r\nelement vertex 1\r\nproperty uchar v\r\nend_header\r\n",
		"blank lines and extra spaces": "ply\n\nformat  binary_big_endian   1.0\n\n  element vertex 1  \nproperty\tuchar\tv\nend_header\n",
	}
	body := "\x00\n\r\x01binary"
	for name, headerText := range tests {
		t.Run(name, func(t *testing.T) {
			r := bufio.NewReader(strings.NewReader(headerText + body))
			h, err := readHeader(r)
			if err != nil {
				t.Fatalf("readHeader: %v", err)
			}
			if h.dataOffset != int64(len(headerText)) {
				t.Errorf("dataOffset = %d, want %d", h.dataOffset, len(headerText))
			}
			if len(h.elements) != 1 || h.elements[0].count != 1 || len(h.elements[0].properties) != 1 {
				t.Errorf("unexpected elements %+v", h.elements)
			}
			rest, err := io.ReadAll(r)
			if err != nil {
				t.Fatalf("read body: %v", err)
			}
			if string(rest) != body {
				t.Errorf("body = %q, want %q", rest, body)
			}
		})
	}
}

func TestReadHeaderAcceptsHeaderWithoutTrailingNewline(t *testing.T) {
	h, err := readHeaderFromString("ply\nformat ascii 1.0\nelement vertex 0\nend_header")
	if err != nil {
		t.Fatalf("readHeader: %v", err)
	}
	if len(h.elements) != 1 || h.elements[0].count != 0 {
		t.Errorf("unexpected elements %+v", h.elements)
	}
}

func TestReadHeaderErrors(t *testing.T) {
	const start = "ply\nformat ascii 1.0\n"
	tests := []struct {
		name    string
		text    string
		wantErr string
	}{
		{"empty input", "", "missing end_header"},
		{"wrong magic", "plyx\nformat ascii 1.0\nend_header\n", "not a PLY file"},
		{"binary garbage", "\x89PNG\r\n\x1a\n", "not a PLY file"},
		{"missing end_header", start + "element vertex 1\nproperty float x\n", "missing end_header"},
		{"missing format", "ply\nelement vertex 1\nproperty float x\nend_header\n", "missing format"},
		{"duplicate format", start + "format ascii 1.0\nend_header\n", "duplicate format"},
		{"unsupported format", "ply\nformat binary_middle_endian 1.0\nend_header\n", `unsupported format "binary_middle_endian"`},
		{"unsupported version", "ply\nformat ascii 2.0\nend_header\n", `unsupported format version "2.0"`},
		{"malformed format", "ply\nformat ascii\nend_header\n", "malformed format line"},
		{"malformed element", start + "element vertex\nend_header\n", "malformed element line"},
		{"non numeric element count", start + "element vertex many\nend_header\n", `invalid element count "many"`},
		{"negative element count", start + "element vertex -1\nend_header\n", `invalid element count "-1"`},
		{"duplicate element", start + "element vertex 1\nelement vertex 2\nend_header\n", `duplicate element "vertex"`},
		{"property before element", start + "property float x\nend_header\n", "property declared before any element"},
		{"unsupported property type", start + "element vertex 1\nproperty float16 x\nend_header\n", `unsupported property type "float16"`},
		{"malformed property", start + "element vertex 1\nproperty float\nend_header\n", "malformed property line"},
		{"duplicate property", start + "element vertex 1\nproperty float x\nproperty double x\nend_header\n", `duplicate property "x" in element "vertex"`},
		{"malformed list property", start + "element face 1\nproperty list uchar int\nend_header\n", "malformed list property line"},
		{"unsupported list count type", start + "element face 1\nproperty list byte int idx\nend_header\n", `unsupported property type "byte"`},
		{"unsupported list value type", start + "element face 1\nproperty list uchar long idx\nend_header\n", `unsupported property type "long"`},
		{"float list count type", start + "element face 1\nproperty list float int idx\nend_header\n", `list count type "float" is not an integer type`},
		{"unknown keyword", start + "elemnt vertex 1\nend_header\n", `unknown keyword "elemnt"`},
		{"error reports line number", start + "element vertex 1\nproperty float16 x\nend_header\n", "line 4"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := readHeaderFromString(tc.text)
			if err == nil {
				t.Fatalf("readHeader succeeded, want error containing %q", tc.wantErr)
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Errorf("error = %q, want it to contain %q", err, tc.wantErr)
			}
		})
	}
}

func TestReadHeaderRejectsLinesLongerThanTheBuffer(t *testing.T) {
	text := "ply\nformat ascii 1.0\ncomment " + strings.Repeat("a", 64) + "\nend_header\n"
	_, err := readHeader(bufio.NewReaderSize(strings.NewReader(text), 32))
	if err == nil || !strings.Contains(err.Error(), "line 3: line too long") {
		t.Errorf("error = %v, want a line too long error on line 3", err)
	}
}

func FuzzReadHeader(f *testing.F) {
	f.Add("ply\nformat binary_little_endian 1.0\nelement vertex 3\nproperty float x\nelement face 1\nproperty list uchar int vertex_indices\nend_header\n")
	f.Add("ply\r\nformat ascii 1.0\r\ncomment c\r\nend_header\r\n")
	f.Add("ply\nformat ascii 1.0\nelement vertex -1\nend_header\n")
	f.Fuzz(func(t *testing.T, text string) {
		h, err := readHeaderFromString(text)
		if err != nil {
			return
		}
		if h.dataOffset > int64(len(text)) {
			t.Errorf("dataOffset %d exceeds input length %d", h.dataOffset, len(text))
		}
		for _, e := range h.elements {
			if e.count < 0 {
				t.Errorf("element %q has negative count %d", e.name, e.count)
			}
			for _, p := range e.properties {
				if p.valueType.size() == 0 {
					t.Errorf("property %q has unsized type %v", p.name, p.valueType)
				}
			}
		}
	})
}
